        console.log(formatNode(node, options));
    }
}

function BaseOptionsListWrapper({canSelectMultipleOptions = false}: BaseOptionsListWrapperProps) {
        const [selectedIds, setSelectedIds] = useState<string[]>([]);

        const sections = [
            {
                data: Array.from({length: 10000}, (_, index) => ({
                    text: `Item ${index}`,
                    keyForList: `item-${index}`,
                    isSelected: selectedIds.includes(`item-${index}`),
                    reportID: `report-${index}`,
                })),
                isDisabled: false,
                shouldShow: true,
                title: 'Section 1',
            },
            {
                data: Array.from({length: 10000}, (_, index) => ({
                    text: `Item ${index}`,
                    keyForList: `item-${index}`,
                    isSelected: selectedIds.includes(`item-${index}`),
                    reportID: `report-${index}`,
                })),
                isDisabled: false,
                shouldShow: true,
                title: 'Section 2',
            },
        ];

        const onSelectRow = (item: OptionData) => {
            if (!item.keyForList) {
                return;
            }

            if (canSelectMultipleOptions) {
                if (selectedIds.includes(item.keyForList)) {
                    setSelectedIds(selectedIds.filter((selectedId) => selectedId === item.keyForList));
                } else {
                    setSelectedIds([...selectedIds, item.keyForList]);
                }
            } else {
                setSelectedIds([item.keyForList]);
            }
        };

        return (
            <BaseOptionsList
                sections={sections}
                headerMessage="Base Options List Header"
                onSelectRow={onSelectRow}
                canSelectMultipleOptions={canSelectMultipleOptions}
            />
        );
    }

function selectOption(select) {
    if (!select) {
        return;
    }

    syncSelectors(select.selectedIndex);

    const allOptions = Array.from(select.options);
    const selectedValue = select.options[select.selectedIndex].value;

    // Hide section that isn't selected, and show section that is selected.
    allOptions.forEach((option) => {
        if (option.value === selectedValue) {
            const toShow = document.getElementsByClassName(option.value);
            for (let i = 0; i < toShow.length; i++) {
                toShow[i].classList.remove('hidden');
            }
            return;
        }

        const toHide = document.getElementsByClassName(option.value);
        for (let i = 0; i < toHide.length; i++) {
            toHide[i].classList.add('hidden');
        }
    });
}

